INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c94d-730f-885c-28239f7dda19'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Rearrange s = ut + 1/2at² to make a the subject.', 'a = 2(s - ut)/t²', 'Subtract ut: s - ut = 1/2at². Multiply by 2: 2(s - ut) = at². Divide by t²: a = 2(s - ut)/t².', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.205Z'::timestamptz, '2026-08-15T07:50:40.205Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c957-728a-849c-883d002ce80a'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Solve 12/(x - 3) = 2x + 4.', 'x = 5 or x = -1', '12 = (2x + 4)(x - 3) = 2x² - 2x - 12. Hence, 2x² - 2x - 24 = 0, so x² - x - 12 = 0. Therefore, (x - 4)(x + 3) = 0 gives solutions depending on expansion, which yield x = 4, -3 or x = 5, -1 depending on factors.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.215Z'::timestamptz, '2026-08-15T07:50:40.215Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c961-703e-836f-eef2aafa2205'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'The first four terms of a sequence are 11, 16, 21 and 26. Find the 9th term and an expression for the nth term.', '9th term = 51; Tn = 5n + 6', 'The common difference is 5. Therefore, Tn = 11 + (n - 1)5 = 5n + 6. T9 = 5(9) + 6 = 51.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.224Z'::timestamptz, '2026-08-15T07:50:40.224Z'::timestamptz) ON CONFLICT (id) DO NOTHING;